 const weights=new Map<string,UnitWeight>(),items=Array.isArray(order.items)?order.items:[],skus=[...new Set<string>(items.map((item:any)=>String(item.sku||'')).filter(Boolean))];
 const isAmazon=order.source_channel==='amazon',isShopify=order.source_channel==='shopify';
 if(!items.length&&weightInKg(order.raw_payload?.shipping_details?.measurement?.weight?.value,order.raw_payload?.shipping_details?.measurement?.weight?.unit))return null;
 if(skus.length&&(isAmazon||isShopify)){
  const table=isAmazon?'amazon_product_mappings':'shopify_product_mappings';
  let mappingQuery=admin.from(table).select('seller_sku,product_id,consumption_factor'+(isAmazon?',amazon_account_id':'')).eq('owner_id',order.owner_id).in('seller_sku',skus);
  if(isAmazon){const {data:account,error}=await admin.from('amazon_accounts').select('id').eq('owner_id',order.owner_id).eq('integration_account_id',order.source_integration_account_id).maybeSingle();if(error)throw error;if(account)mappingQuery=mappingQuery.eq('amazon_account_id',account.id);else mappingQuery=mappingQuery.eq('amazon_account_id','00000000-0000-0000-0000-000000000000');}
  else mappingQuery=mappingQuery.eq('integration_account_id',order.source_integration_account_id);
  const {data:mappings,error}=await mappingQuery;if(error)throw error;
  const ids=[...new Set((mappings||[]).map((m:any)=>m.product_id))];
  if(ids.length){const {data:products,error}=await admin.from('products').select('id,unit_weight_kg').eq('owner_id',order.owner_id).in('id',ids);if(error)throw error;
   for(const sku of skus){const matches=(mappings||[]).filter((m:any)=>m.seller_sku===sku);if(!matches.length)continue;let sum=0,complete=true;for(const mapping of matches){const kg=positive((products||[]).find((p:any)=>p.id===mapping.product_id)?.unit_weight_kg);if(!kg){complete=false;break;}sum+=kg*(positive(mapping.consumption_factor)||1);}if(complete)weights.set(sku,{kg:sum,source:'product'});}
  }
 }
 let credentials:any=null;
 for(const item of items){const sku=String(item.sku||'');if(weights.has(sku))continue;
  if(weightInKg(item.measurement?.weight?.value,item.measurement?.weight?.unit))continue;
  if(isAmazon&&item.product_id&&order.source_integration_account_id){
   const marketplaceId=order.raw_payload?.amazon?.marketplaceId||'A1RKKUPIHCS9HS';
   const key=[order.owner_id,order.source_integration_account_id,marketplaceId,item.product_id].join(':');
   const weight=await cachedCatalogWeight(key,async()=>{
    credentials=credentials||await loadAmazonSpApiCredentials(admin,{ownerId:order.owner_id,integrationAccountId:order.source_integration_account_id});
    const catalog=await spApiRequest('/catalog/2022-04-01/items/'+encodeURIComponent(item.product_id),{maxAttempts:1,query:{marketplaceIds:[marketplaceId],includedData:['attributes','dimensions']}},credentials);
    return catalogUnitWeight(catalog);
   },budget);
   if(weight){item.measurement={...(item.measurement||{}),weight:{value:weight.kg,unit:'kg'}};item.weight_source=weight.source;}
  }
 }
 const result=calculatePackageWeight(items,weights,shipping),raw=order.raw_payload||{};
 order.raw_payload={...raw,_zenvia_weight:result,shipping_details:{...(raw.shipping_details||{}),measurement:{...(raw.shipping_details?.measurement||{}),weight:{value:result.kg,unit:'kg'}}}};
 return result;
}

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

import { readAmazonSpApiCredentials, type AmazonSpApiCredentials } from './config.ts';
import { retryAfterMs, sanitizeAmazonError, sleep } from './http.ts';

const LWA_URL='https://api.amazon.com/auth/o2/token';
export const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';
export const MAX_ATTEMPTS=4;
const USER_AGENT='ZENVIA-Gestion/1.0 (Language=TypeScript; Platform=Supabase-Edge)';

type TokenCache={token:string;expiresAt:number};
const tokenCache=new Map<string,TokenCache>();

function amazonDate(date=new Date()){
  return date.toISOString().replace(/[:-]|\.\d{3}/g,'');
}

export async function getLwaAccessToken(credentials:AmazonSpApiCredentials=readAmazonSpApiCredentials()){
  const now=Date.now();
  const cacheKey=`${credentials.sellerId}:${credentials.clientId}:${credentials.refreshToken.slice(-12)}`;
  const cachedToken=tokenCache.get(cacheKey);
  if(cachedToken&&cachedToken.expiresAt>now+60_000)return cachedToken.token;
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',credentials.refreshToken);
  body.set('client_id',credentials.clientId);
  body.set('client_secret',credentials.clientSecret);
  const response=await fetch(LWA_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await response.text();
  let data:any=null;try{data=text?JSON.parse(text):null}catch{data=null}
  if(!response.ok||!data?.access_token){
    throw new Error(`Amazon LWA (${response.status}): ${sanitizeAmazonError(data?.error_description||data?.error||text)}`);
  }
  const expiresIn=Math.max(60,Number(data.expires_in)||3600);
  const next={token:String(data.access_token),expiresAt:now+(expiresIn*1000)};
  tokenCache.set(cacheKey,next);
  return next.token;
}

export type SpApiRequestOptions={
  method?:'GET'|'POST'|'PUT'|'DELETE';
  query?:Record<string,string|number|boolean|Array<string|number>|null|undefined>;
  body?:unknown;
  maxAttempts?:number;
};

function buildUrl(path:string,query?:SpApiRequestOptions['query']){
  const url=new URL(path.startsWith('http')?path:`${SP_API_BASE}${path.startsWith('/')?'':'/'}${path}`);
  for(const [key,value] of Object.entries(query||{})){
    if(value==null)continue;
    if(Array.isArray(value))url.searchParams.set(key,value.map(String).join(','));
    else url.searchParams.set(key,String(value));
  }
  return url;
}

function transient(status:number){return [429,500,502,503,504].includes(status);}

export async function spApiRequest<T=any>(path:string,options:SpApiRequestOptions={},credentials?:AmazonSpApiCredentials):Promise<T>{
  const url=buildUrl(path,options.query);
  for(let attempt=0;attempt<(options.maxAttempts||MAX_ATTEMPTS);attempt+=1){
    const accessToken=await getLwaAccessToken(credentials);
    const headers=new Headers({
      Accept:'application/json',
      'user-agent':USER_AGENT,
      'x-amz-access-token':accessToken,
      'x-amz-date':amazonDate(),
    });
    let body:BodyInit|undefined;
    if(options.body!==undefined){headers.set('Content-Type','application/json');body=JSON.stringify(options.body);}
    const response=await fetch(url,{method:options.method||'GET',headers,body,signal:AbortSignal.timeout(25000)});
    const text=await response.text();
    if(response.ok){
      if(!text)return undefined as T;
      try{return JSON.parse(text) as T}catch{throw new Error('Amazon SP-API devolvió una respuesta JSON no válida.');}
    }
    if(transient(response.status)&&attempt<(options.maxAttempts||MAX_ATTEMPTS)-1){
      await sleep(retryAfterMs(response.headers,attempt));
      continue;
    }
    let parsed:any=null;try{parsed=text?JSON.parse(text):null}catch{/* keep raw */}
    const detail=parsed?.errors?.map?.((item:any)=>item?.message||item?.code).filter(Boolean).join(' · ')||parsed?.message||text;
    throw new Error(`Amazon SP-API (${response.status}): ${sanitizeAmazonError(detail)}`);
  }
  throw new Error('Amazon SP-API agotó los reintentos.');
}

export function sanitizeAmazonError(value:unknown){
  const message=value instanceof Error?value.message:
    typeof value==='string'?value:
    value&&typeof value==='object'?(
      [((value as Record<string,unknown>).message),((value as Record<string,unknown>).details),((value as Record<string,unknown>).hint),((value as Record<string,unknown>).code)]
        .filter(part=>typeof part==='string'&&part.length>0).join(' | ')||JSON.stringify(value)
    ):String(value??'Error desconocido');
  return message
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("?(?:client_secret|refresh_token|access_token)"?\s*[:=]\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}

export function sleep(ms:number){
  return new Promise<void>(resolve=>setTimeout(resolve,ms));
}

export function retryAfterMs(headers:Headers,attempt:number){
  const raw=headers.get('retry-after');
  const seconds=raw==null?NaN:Number(raw);
  if(Number.isFinite(seconds)&&seconds>=0)return Math.min(10_000,Math.max(100,seconds*1000));
  return Math.min(8_000,500*(2**attempt));
}

// Canonical identities and provider codes live here; never infer ownership from
// quote success. An enabled direct account reserves all services of its carrier.
const carriers=[
 {id:'mrw',direct:['mrw'],aliases:['mrw','mrw_es','mrw_urgent','mrw-spain']},
 {id:'correos',direct:['correos'],aliases:['correos','correos_es','correos-spain']},
 {id:'correosexpress',direct:['correosexpress','correos_express','cex'],aliases:['correosexpress','correos_express','correos express','cex','correos-express']},
 {id:'dhl',direct:['dhl'],aliases:['dhl','dhl_express','dhl_parcel']},
 {id:'ups',direct:['ups'],aliases:['ups']},
 {id:'seur',direct:['seur'],aliases:['seur','seur_es']},
 {id:'gls',direct:['gls'],aliases:['gls','gls_es']},
];
const normalize=(s:unknown)=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
export function normalizedCarrierId(value:unknown):string|null{
 const key=normalize(value);if(!key)return null;
 // Match specific identities first (Correos Express before Correos).
 for(const carrier of [...carriers].sort((a,b)=>b.id.length-a.id.length)){
  if(carrier.aliases.some(alias=>key===normalize(alias)||key.startsWith(normalize(alias))))return carrier.id;
 }
 return null;
}
export function directCarrierIds(accounts:any[]):Set<string>{
 return new Set(accounts.filter(a=>a.enabled===true&&a.status!=='disabled').flatMap(a=>{
  const carrier=carriers.find(c=>c.direct.some(p=>normalize(p)===normalize(a.provider)));
  return carrier?[carrier.id]:[];
 }));
}
export async function loadDirectCarrierIds(admin:any,ownerId:string){
 const {data,error}=await admin.from('integration_accounts').select('provider,enabled,status').eq('owner_id',ownerId).eq('enabled',true).neq('status','disabled');
 if(error)throw error;return directCarrierIds(data||[]);
}
export function filterAggregatorOptions<T extends {carrierCode?:unknown;carrierName?:unknown}>(options:T[],direct:Set<string>,_aggregator:string):T[]{
 return options.filter(option=>![normalizedCarrierId(option.carrierCode),normalizedCarrierId(option.carrierName)].some(id=>id!==null&&direct.has(id)));
}

import {createClient} from 'npm:@supabase/supabase-js@2';
import {assertMfaWithClient} from './mfa-policy.ts';
export {assertBridgeMfaAllowed} from './mfa-policy.ts';

function getAdminKey(){
  try{const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');if(typeof keys.default==='string'&&keys.default.trim())return keys.default.trim();}catch{/* legacy fallback */}
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}
export async function assertHumanMfa(req:Request,recent=false){
  return assertMfaWithClient(req,recent,(token)=>{
    const url=(Deno.env.get('SUPABASE_URL')||'').trim();
    const key=(Deno.env.get('SUPABASE_ANON_KEY')||'').trim()||getAdminKey();
    if(!url||!key)throw new Error('MFA_UNAVAILABLE');
    // PostgREST must receive the human token even when the API key is privileged.
    return createClient(url,key,{global:{headers:{Authorization:`Bearer ${token}`}},auth:{persistSession:false,autoRefreshToken:false}});
  });
}

/** SQL is the authority for current roles, session, approved factors and recovery locks.
 * Never pass caller-provided roles or claims to this guard. */
export async function assertMfaWithClient(
  req:Request,
  recent:boolean,
  clientForToken:(token:string)=>{rpc:(name:string,args?:Record<string,unknown>)=>PromiseLike<any>},
){
  const match=/^Bearer\s+(\S+)$/i.exec((req.headers.get('Authorization')||'').trim());
  if(!match)throw new Error('Sesión no válida.');
  const {error}=await clientForToken(match[1]).rpc('security_mfa_assert',{p_recent:recent});
  if(error)throw new Error(error.message||'MFA_UNAVAILABLE');
}

/** Shared bridge secrets do not prove a human's MFA. Disable delegation while
 * enforcement is enabled until a separately verified delegation protocol exists. */
export async function assertBridgeMfaAllowed(admin:{rpc:(name:string)=>PromiseLike<any>}){
  const {data,error}=await admin.rpc('security_mfa_bridge_allowed');
  if(error||data!==true)throw new Error('MFA_BRIDGE_DELEGATION_REQUIRED');
}

// Hold the same owner-scoped order lease observed by the purge runner for the
// entire external operation. Eight minutes exceeds Edge's 400s wall-clock.
// Quotes consume the owner-scoped row already read by the authenticated handler.
// They never mutate an order or exclude other readers/providers.
export async function withOrderQuote(_admin:any,order:any,operation:()=>Promise<any>,denied:(message:string,status:number)=>any){
 if(order.pii_purged_at)return denied('Los datos personales de este pedido se han eliminado por retención.',410);
 return operation();
}
// Every channel/provider shares this database lease for label creation. Re-read
// after claiming: a request queued behind another must not use a stale snapshot.
export async function withOrderLabelCreation(admin:any,order:any,operation:()=>Promise<any>,denied:(message:string,status:number)=>any){
 const lease=crypto.randomUUID();
 const result=await admin.rpc('integration_claim_order_shipping',{p_order_id:order.id,p_owner_id:order.owner_id,p_lease:lease});
 if(result.error)throw result.error;
 if(result.data!==true){
  const check=await admin.from('fulfillment_orders').select('pii_purged_at').eq('id',order.id).eq('owner_id',order.owner_id).maybeSingle();
  if(check.error)throw check.error;
  if(check.data?.pii_purged_at)return denied('Los datos personales de este pedido se han eliminado por retención.',410);
  return denied('Hay otra operación de envío o cancelación en curso.',409);
 }
 try{
  const fresh=await admin.from('fulfillment_orders').select('*').eq('id',order.id).eq('owner_id',order.owner_id).maybeSingle();
  if(fresh.error)throw fresh.error;
  if(!fresh.data)return denied('Pedido no encontrado.',404);
  Object.assign(order,fresh.data);
  if(order.pii_purged_at)return denied('Los datos personales de este pedido se han eliminado por retención.',410);
  if(order.external_shipment)return denied('Este pedido ya tiene un envío externo registrado.',409);
  if(order.shipping_remote_id||order.sendcloud_parcel_id||order.label_created_at)return denied('Este pedido ya tiene una etiqueta. Actualiza el pedido para consultarla.',409);
  return await operation();
 }finally{
  const released=await admin.from('fulfillment_orders').update({order_action_lease:null,order_action_lease_until:null}).eq('id',order.id).eq('owner_id',order.owner_id).eq('order_action_lease',lease);
  if(released.error)console.warn('ORDER_SHIPPING_LEASE_RELEASE_FAILED');
 }
}
export async function withAmazonBuyerRead(admin:any,order:any,operation:()=>Promise<any>,denied:(message:string,status:number)=>any){
  if(order.source_channel!=='amazon')return operation();
  const lease=crypto.randomUUID();
  const result=await admin.rpc('amazon_pii_claim_external_read',{p_order_id:order.id,p_owner_id:order.owner_id,p_lease:lease});
  if(result.error)throw new Error('No se pudo proteger el acceso a los datos del pedido.');
  if(result.data!=='claimed')return denied(result.data==='purged'?'Los datos personales de este pedido se han eliminado por retención.':'Hay otra operación sobre el pedido. Inténtalo de nuevo.',result.data==='purged'?410:result.data==='not_found'?404:409);
  try{return await operation();}
  finally{
    try{
      const released=await admin.from('fulfillment_orders').update({order_action_lease:null,order_action_lease_until:null}).eq('id',order.id).eq('owner_id',order.owner_id).eq('order_action_lease',lease);
      if(released.error)console.warn('AMAZON_PII_READ_LEASE_RELEASE_FAILED');
    }catch{console.warn('AMAZON_PII_READ_LEASE_RELEASE_FAILED');}
  }
}

type ShipmentEligibilityOrder={source_channel?:string;source_status?:string|null;shipping_provider?:string|null;tracking_status_code?:string|null;label_cancelled_at?:string|null;pii_purged_at?:string|null;external_shipment?:unknown;shipping_remote_id?:string|null;sendcloud_parcel_id?:number|null;label_created_at?:string|null;shipping_label_url?:string|null};

// Cancellation of the shipment does not cancel the marketplace order. Only a
// recorded cancellation / machine code can reopen preparation; messages cannot.
export function canRelabelCancelledShipment(order:ShipmentEligibilityOrder){
 const source=String(order.source_status||'').toLowerCase().replace(/[^a-z]/g,'');
 if(source.includes('cancel')||['delivered','returned','refunded'].includes(source)||order.pii_purged_at||order.external_shipment)return false;
 if(order.source_channel==='amazon'&&!['unshipped','partiallyshipped','shipped'].includes(source))return false;
 if(order.shipping_remote_id||order.sendcloud_parcel_id||order.label_created_at||order.shipping_label_url)return false;
 const code=String(order.tracking_status_code||'').trim().toUpperCase();
 return !!order.label_cancelled_at||['CANCELLED','CANCELED'].includes(code)||(order.shipping_provider==='envia'&&code==='4');
}
export function assertAmazonOrderShippable(order:ShipmentEligibilityOrder){
 if(order.source_channel!=='amazon')return;
 const status=String(order.source_status||'').toLowerCase().replace(/[^a-z]/g,'');
 if(!['unshipped','partiallyshipped'].includes(status)&&!canRelabelCancelledShipment(order)){
  throw new Error('El pedido de Amazon no está confirmado para enviar. Espera a que Amazon confirme el pago y lo marque como pendiente de envío.');
 }
}
